private function maskQuotedSheetSeparators(string $value): string
{
    $masked = '';
    $inQuotes = false;
    $length = strlen($value);
    for ($i = 0; $i < $length; ++$i) {
        $character = $value[$i];
        if ($character === "'") {
            if ($inQuotes && $i + 1 < $length && $value[$i + 1] === "'") {
                $masked .= "''";
                ++$i;
                continue;
            }
            $inQuotes = !$inQuotes;
            $masked .= $character;
            continue;
        }
        if ($inQuotes && ($character === '.' || $character === ':')) {
            $masked .= "\x1A";
        } else {
            $masked .= $character;
        }
    }

    return $masked;
}

private function unmaskQuotedSheetSeparators(string $value): string
{
    return str_replace("\x1A", '.', $value);
}

